CREATE TABLE locations (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, location_text TEXT NOT NULL, location_precision TEXT NOT NULL DEFAULT 'unknown' CHECK (location_precision IN ('unknown','approximate','address','coordinates')), location_kind TEXT NULL, longitude REAL NULL CHECK (longitude BETWEEN -180 AND 180), latitude REAL NULL CHECK (latitude BETWEEN -90 AND 90), location_radius_meters REAL NULL CHECK (location_radius_meters >= 0), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','merged','retired')), merged_into_id TEXT NULL REFERENCES locations(id) ON DELETE SET NULL, created_by_user_id TEXT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
-- statement-break
CREATE INDEX idx_locations_case_status ON locations(case_id, status, updated_at);
